"""Cross-platform font file resolution (Windows system fonts, or Linux metric-compatible equivalents).

Used by the fallback PDF writer and the DOCX avatar renderer. In the Docker image the Linux fonts come from
fonts-crosextra-carlito/caladea, fonts-liberation, fonts-dejavu-core, fonts-noto-core and fonts-noto-cjk.
"""
import os

WIN_DIR = os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts")
_T = "/usr/share/fonts/truetype"
_CJK = "/usr/share/fonts/opentype/noto"

# windows file name -> list of (linux path, collection index); first existing wins
LINUX_EQUIVALENTS: dict[str, list[tuple[str, int]]] = {
    "calibri.ttf": [(f"{_T}/crosextra/Carlito-Regular.ttf", 0)],
    "calibrib.ttf": [(f"{_T}/crosextra/Carlito-Bold.ttf", 0)],
    "cambria.ttc": [(f"{_T}/crosextra/Caladea-Regular.ttf", 0)],
    "cambriab.ttf": [(f"{_T}/crosextra/Caladea-Bold.ttf", 0)],
    "times.ttf": [(f"{_T}/liberation/LiberationSerif-Regular.ttf", 0)],
    "timesbd.ttf": [(f"{_T}/liberation/LiberationSerif-Bold.ttf", 0)],
    "georgia.ttf": [(f"{_T}/liberation/LiberationSerif-Regular.ttf", 0)],
    "georgiab.ttf": [(f"{_T}/liberation/LiberationSerif-Bold.ttf", 0)],
    "segoeui.ttf": [(f"{_T}/noto/NotoSans-Regular.ttf", 0), (f"{_T}/dejavu/DejaVuSans.ttf", 0)],
    "segoeuib.ttf": [(f"{_T}/noto/NotoSans-Bold.ttf", 0), (f"{_T}/dejavu/DejaVuSans-Bold.ttf", 0)],
    # DejaVu Sans also covers Arabic, which the fallback writer renders with the "arial" family
    "arial.ttf": [(f"{_T}/dejavu/DejaVuSans.ttf", 0)],
    "arialbd.ttf": [(f"{_T}/dejavu/DejaVuSans-Bold.ttf", 0)],
    "verdana.ttf": [(f"{_T}/dejavu/DejaVuSans.ttf", 0)],
    "verdanab.ttf": [(f"{_T}/dejavu/DejaVuSans-Bold.ttf", 0)],
    "Nirmala.ttc#0": [(f"{_T}/noto/NotoSansDevanagari-Regular.ttf", 0)],
    "Nirmala.ttc#1": [(f"{_T}/noto/NotoSansDevanagari-Bold.ttf", 0)],
    "msyh.ttc": [(f"{_CJK}/NotoSansCJK-Regular.ttc", 2)],  # index 2 = Simplified Chinese
    "msyhbd.ttc": [(f"{_CJK}/NotoSansCJK-Bold.ttc", 2)],
}
LAST_RESORT = [(f"{_T}/dejavu/DejaVuSans.ttf", 0)]


def font_file(win_name: str, index: int = 0) -> tuple[str, int]:
    """Return (path, collection index) for a Windows font name on the current platform."""
    win_path = os.path.join(WIN_DIR, win_name)
    if os.name == "nt" and os.path.exists(win_path):
        return win_path, index
    for key in (f"{win_name}#{index}", win_name):
        for path, idx in LINUX_EQUIVALENTS.get(key, []):
            if os.path.exists(path):
                return path, idx
    for path, idx in LAST_RESORT:
        if os.path.exists(path):
            return path, idx
    return win_path, index  # let the caller raise a clear "file not found"
